transforms.post:
(
  $q := "query Query($where: EventListWhereInput) {\n  eventList(where: $where){\n    edges{\n      node{  requireNote eventId }\n    }\n  }\n}\n";
  $eventList := $query({
    "statement": $q,
    "variables":{
      "where": {
        "id": {"_eq": result.event }
      }
    }
  }).eventList.edges.node;

  $output:= {
    "eventId": $eventList.eventId,
    "message": result.message
  };
  $requireNote = true and $isNilOrEmpty(result.message)? $throw("This event requires a note."): $output
)
